SELECT  FROM upstream_subscription_accounts
WHERE (#{provider} IS NULL OR #{provider} = '' OR provider = #{provider})
ORDER BY priority DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE upstream_subscription_accounts
name = #{changes.name}, auth_type = #{changes.auth_type}, email = #{changes.email}, account_ref = #{changes.account_ref}, credentials_encrypted = #{changes.credentials_encrypted}, models_json = #{changes.models_json}, model_pricing_json = #{changes.model_pricing_json}, enabled = #{changes.enabled}, priority = #{changes.priority}, weight = #{changes.weight}, input_price_cny = #{changes.input_price_cny}, output_price_cny = #{changes.output_price_cny}, price_multiplier = #{changes.price_multiplier}, status = #{changes.status}, error_count = #{changes.error_count}, last_error = #{changes.last_error}, expires_at = #{changes.expires_at}, cooldown_until = #{changes.cooldown_until}, updated_at = #{changes.updated_at},
WHERE id = #{account_id}

UPDATE upstream_subscription_accounts
SET credentials_encrypted = #{credentials_encrypted}, email = #{email}, account_ref = #{account_ref},
    expires_at = #{expires_at}, status = 'READY', error_count = 0, last_error = '', cooldown_until = NULL, updated_at = #{updated_at}
WHERE id = #{account_id}

UPDATE upstream_subscription_accounts
SET status = #{status}, error_count = #{error_count}, last_error = #{last_error},
    cooldown_until = #{cooldown_until}, last_used_at = #{last_used_at}, updated_at = #{updated_at}
WHERE id = #{account_id}

UPDATE upstream_subscription_accounts
SET enabled = 0, status = 'DISABLED', error_count = #{error_count},
    last_error = #{last_error}, cooldown_until = NULL,
    last_used_at = #{last_used_at}, updated_at = #{updated_at}
WHERE id = #{account_id}

UPDATE upstream_config_requests
SET status=#{status}, admin_note=#{admin_note}, updated_at=#{updated_at}
WHERE id=#{request_id}
